def _extensions() -> None:
    # En Supabase las extensiones viven en el esquema "extensions"; en local, en public.
    op.execute(
        """
        DO $$
        DECLARE target text := CASE WHEN EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = 'extensions')
                                    THEN 'extensions' ELSE 'public' END;
        BEGIN
          EXECUTE format('CREATE EXTENSION IF NOT EXISTS unaccent WITH SCHEMA %I', target);
          EXECUTE format('CREATE EXTENSION IF NOT EXISTS pg_trgm WITH SCHEMA %I', target);
        END $$;
        """
    )
    # unaccent() no es IMMUTABLE; este envoltorio permite usarlo en índices y columnas generadas.
    op.execute(
        """
        DO $$
        DECLARE ext_schema text := (SELECT n.nspname FROM pg_extension e JOIN pg_namespace n ON n.oid = e.extnamespace
                                     WHERE e.extname = 'unaccent');
        BEGIN
          EXECUTE format($f$
            CREATE OR REPLACE FUNCTION public.f_unaccent(text) RETURNS text
            LANGUAGE sql IMMUTABLE PARALLEL SAFE STRICT
            AS $body$ SELECT %I.unaccent(%L::regdictionary, $1) $body$
          $f$, ext_schema, ext_schema || '.unaccent');
        END $$;
        """
    )


def _post_schema() -> None:
    op.execute(
        """
        ALTER TABLE search_index ADD COLUMN tsv tsvector GENERATED ALWAYS AS (
          setweight(to_tsvector('spanish', public.f_unaccent(coalesce(title, ''))), 'A') ||
          setweight(to_tsvector('spanish', public.f_unaccent(coalesce(ref_code, '') || ' ' ||
                    coalesce(institution_name, '') || ' ' || coalesce(supplier_name, ''))), 'B') ||
          setweight(to_tsvector('spanish', public.f_unaccent(coalesce(body, ''))), 'C')
        ) STORED
        """
    )
    op.execute("CREATE INDEX ix_search_tsv ON search_index USING gin (tsv)")
    op.execute(
        """
        DO $$
        DECLARE ext_schema text := (SELECT n.nspname FROM pg_extension e JOIN pg_namespace n ON n.oid = e.extnamespace
                                     WHERE e.extname = 'pg_trgm');
        BEGIN
          EXECUTE format('CREATE INDEX ix_search_title_trgm ON search_index USING gin (lower(public.f_unaccent(title)) %I.gin_trgm_ops)', ext_schema);
          EXECUTE format('CREATE INDEX ix_institutions_name_trgm ON institutions USING gin (lower(public.f_unaccent(name)) %I.gin_trgm_ops)', ext_schema);
          EXECUTE format('CREATE INDEX ix_suppliers_name_trgm ON suppliers USING gin (lower(public.f_unaccent(name)) %I.gin_trgm_ops)', ext_schema);
        END $$;
        """
    )
    op.execute("CREATE INDEX ix_search_ref_code ON search_index (lower(ref_code))")
    op.execute("CREATE INDEX ix_search_inst ON search_index (institution_id, event_date DESC)")
    op.execute("CREATE INDEX ix_contracts_supplier_date ON contracts (supplier_id, awarded_at DESC)")
    op.execute("CREATE INDEX ix_contracts_inst_date ON contracts (institution_id, awarded_at DESC)")
    op.execute(
        "CREATE UNLOGGED TABLE rate_limit_buckets (key text PRIMARY KEY, window_start timestamptz NOT NULL, count integer NOT NULL)"
    )
    # Permisos del rol de la web (si existe): lectura general + escritura mínima.
    op.execute(
        """
        DO $$
        BEGIN
          IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'web_app') THEN
            GRANT USAGE ON SCHEMA public TO web_app;
            GRANT SELECT ON ALL TABLES IN SCHEMA public TO web_app;
            REVOKE SELECT ON admin_users FROM web_app;
            GRANT SELECT (id, email, display_name, password_hash, role, active, failed_attempts, locked_until, last_login_at)
              ON admin_users TO web_app;
            GRANT UPDATE (failed_attempts, locked_until, last_login_at) ON admin_users TO web_app;
            GRANT INSERT ON correction_requests, audit_logs, alert_status_history, detection_rules TO web_app;
            GRANT UPDATE (status, resolution, handled_by, handled_at) ON correction_requests TO web_app;
            GRANT UPDATE (status, public_label) ON alerts TO web_app;
            GRANT UPDATE (active) ON detection_rules TO web_app;
            GRANT INSERT, UPDATE ON system_settings TO web_app;
            GRANT INSERT, UPDATE, DELETE ON rate_limit_buckets TO web_app;
            GRANT USAGE ON ALL SEQUENCES IN SCHEMA public TO web_app;
            GRANT EXECUTE ON FUNCTION public.f_unaccent(text) TO web_app;
          END IF;
        END $$;
        """
    )
